1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Computes an owner's {@code identityKey}: a derived, human-readable summary of the fields
7	 * that identify an owner. The key is
8	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
9	 *
10	 * <p>Household membership itself is enforced separately by {@link RequireUniqueIdentity},
11	 * which rejects a second owner in the same household (same {@code householdId}, derived from
12	 * lastName + postcode) unless it declares {@code sharesHousehold}.
13	 *
14	 * <ul>
15	 * <li>telephone is normalized to E.164 form ({@link Telephones#toE164(String)}),
16	 * <li>email is trimmed and lower-cased, contributing empty when absent,
17	 * <li>householdId is the owner's deterministic household identifier (from lastName +
18	 *     postcode), empty only when it has not been assigned.
19	 * </ul>
20	 */
21	public final class IdentityKeys {
22	
23	    private IdentityKeys() {
24	    }
25	
26	    /** The identity key of an existing owner, from its stored fields. */
27	    public static String forOwner(Owner owner) {
28	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
29	    }
30	
31	    private static String build(String telephone, String email, String householdId) {
32	        String tel = Telephones.toE164(telephone);
33	        return (tel == null ? "" : tel) + "|" + normalizeEmail(email) + "|"
34	                + (householdId == null ? "" : householdId);
35	    }
36	
37	    /** Trim and lower-case; null or blank yields empty (no email to contribute). */
38	    private static String normalizeEmail(String email) {
39	        if (email == null || email.isBlank()) {
40	            return "";
41	        }
42	        return email.trim().toLowerCase();
43	    }
44	}
