20	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
21	    public static int luhn(String value) {
22	        if (value == null) {
23	            return 0;
24	        }
25	        int sum = 0;
26	        boolean dbl = true;
27	        for (int i = value.length() - 1; i >= 0; i--) {
28	            char c = value.charAt(i);
29	            if (c < '0' || c > '9') {
30	                continue;
31	            }
32	            int d = c - '0';
33	            if (dbl) {
34	                d *= 2;
35	                if (d > 9) {
36	                    d -= 9;
37	                }
38	            }
39	            sum += d;
40	            dbl = !dbl;
41	        }
42	        return (10 - (sum % 10)) % 10;
43	    }
44	}
