12	 * so the field is simply absent from the response.
13	 */
14	public final class AgeBands {
15	
16	    private AgeBands() {
17	    }
18	
19	    /** The age band for the given owner, or {@code null} when no birth date is set. */
20	    public static String forOwner(Owner owner) {
21	        LocalDate birthDate = owner.getBirthDate();
22	        if (birthDate == null) {
23	            return null;
24	        }
25	        // Age is measured against the registration date, defaulting to today when absent.
26	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
27	        long years = ChronoUnit.YEARS.between(birthDate, asOf);
28	        if (years < 18) {
29	            return "MINOR";
30	        }
31	        if (years < 65) {
32	            return "ADULT";
33	        }
34	        return "SENIOR";
35	    }
36	}
